#include <bits/stdc++.h>

using namespace std;

typedef long long ll;

struct UnionFind {
    vector<int> parent, size;
    int components;
    UnionFind(int n) : parent(n), size(n, 1), components(0) {
        for (int i = 0; i < n; ++i) parent[i] = i;
    }
    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    bool unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y) return false;
        if (size[x] < size[y]) swap(x, y);
        parent[y] = x;
        size[x] += size[y];
        return true;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int p, k;
    cin >> p >> k;
    const int MOD = 1000000007;
    long long result = 1;
    if (k == 0) {
        for (int i = 0; i < p - 1; ++i) {
            result = (result * p) % MOD;
        }
    } else {
        UnionFind uf(p);
        int cc = p;
        for (int i = 0; i < p; ++i) {
            int to = (long long)k * i % p;
            if (uf.unite(i, to)) {
                cc--;
            }
        }
        if (k > 1) {
            // count components via uf
            set<int> comps;
            for (int i = 0; i < p; ++i) {
                comps.insert(uf.find(i));
            }
            cc = (int)comps.size();
        }
        for (int i = 0; i < cc; ++i) {
            result = (result * p) % MOD;
        }
    }
    cout << result << "\n";
    return 0;
}
